window.kbPageData["views/entry/k-61c3300d8176cfca"] = {"key":"entry/k-61c3300d8176cfca","state":{"route":"entry/k-61c3300d8176cfca"},"node":{"id":"k-61c3300d8176cfca","mode":"k","title":"同一整体下的比重之比","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["同一整体下两个部分的量之比等于各自的比重之比"],"qs":["江苏 2025 C类 行测#111"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"两个部分以同一个非零总量为分母计算比重时，两个部分量之比等于各自的比重之比。已知其中一个部分量和两个比重，就可以求出另一个部分量。","review":{"definition":"两个部分以同一个非零总量为分母计算比重时，两个部分量之比等于各自的比重之比。已知其中一个部分量和两个比重，就可以求出另一个部分量。","explanation":"江苏 2025 C类行测第111题中，工业增加值和制造业增加值的比重都以2023年我国GDP为分母。两项比重相除时，GDP约去。因此，制造业增加值约为39.9×（26.2%÷31.7%）≈33.0万亿元，对应C项。","references":[],"evidence":"我国工业增加值占GDP比重为31.7%，制造业增加值占GDP比重为26.2%","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 C类 行测#111":{"paper":"江苏 2025 C类 行测","n":111,"mod":"资料分析","src":["ffc394a1c160f331ec57.pdf",23],"asrc":["d1de3b437151c05b769e.pdf",34],"card":"cb156be9e73718a2605df5e3","links":[{"id":"k-61c3300d8176cfca","role":"解题依据","why":"两项增加值以同一年度GDP为分母，可以用比重之比换算部分量。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-61c3300d8176cfca":[["江苏 2025 C类 行测#111"]]}};
